import sys

data = sys.stdin.read().split()
r, c = int(data[0]), int(data[1])
h = [[int(data[2 + i * c + j]) for j in range(c)] for i in range(r)]
out = []
for i in range(r):
    for j in range(c):
        seen = {(i, j)}
        stack = [(i, j)]
        p = a = False
        while stack:
            x, y = stack.pop()
            if x == 0 or y == 0:
                p = True
            if x == r - 1 or y == c - 1:
                a = True
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                u, v = x + dx, y + dy
                if 0 <= u < r and 0 <= v < c and (u, v) not in seen and h[u][v] <= h[x][y]:
                    seen.add((u, v))
                    stack.append((u, v))
        if p and a:
            out.append(f"{i} {j}")
print("\n".join(out))

